import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.SQLException;

public class SecureDatabaseQuery {
    public String executeQuerySafe(String userInput) throws SQLException {
        // Define the SQL query with a placeholder (?) for the user input.
        // The position of the placeholder indicates where the user input will be inserted.
        String sql = "SELECT * FROM users WHERE name = ?";

        // Create a PreparedStatement object.
        // This object allows us to set parameters safely without concatenating strings.
        try (Connection conn = getConnection(); 
             PreparedStatement pstmt = conn.prepareStatement(sql)) {

